// SET YOUR OPERATOR EMAIL HERE — the one address for operator-facing
// mail: the error alert AND the run-digest email both send to it.
// It is its own node because Workflow Config does not run inside an
// error-triggered execution: a `$('Workflow Config')` lookup would throw.
// Keep it as a literal, or point it at anything that resolves here.
return [{ json: { to: 'owner@example.com' } }];

// Error Trigger payload -> one alert email body for the operator. Runs
// only inside an error-triggered execution: 'Operator email' also fires
// from the digest gate on live runs, and there 'On workflow error' has no
// data — the lookup doubles as the lane guard (no error payload -> zero
// items -> 'Email owner: workflow error' stays silent). The trigger item
// carries the real error context; the address comes from the {to} item
// 'Operator email' emitted (Workflow Config cannot be referenced here).
let trigger;
try { trigger = $('On workflow error').first().json; } catch (e) { return []; }
const e = trigger.execution || {};
const w = trigger.workflow || {};
const err = (e.error && e.error.message) || 'workflow error';
const node = (e.error && e.error.lastNodeExecuted) || 'unknown';
const to = $input.first().json.to || 'owner@example.com';
return [{ json: {
  to,
  subject: `Weekly report workflow failed: ${w.name || 'client-report-generator'}`,
  body: `Execution ${e.id || '?'} failed at node ${node}: ${err}\nExecution: ${e.url || 'n/a'}`,
} }];

// The ONLY node you edit after running the setup lane once.
//   sheet_id — printed by the SETUP lane (or your own workbook with
//              'config' and 'reports' tabs)
// The operator email lives in the dedicated 'Operator email' node
// (Workflow Config cannot be referenced from an error-triggered
// execution, and it feeds the run digest too).
return {
  json: {
    sheet_id: 'PASTE_SPREADSHEET_ID_HERE',
  },
};

// One item: the set of already-sent dedupe keys (client_id+ISO week).
// Read lazily by 'Dedupe check' so a missing/empty ledger can never crash
// the demo lane — the lookup is wrapped there.
return [{
  json: {
    sent_keys: $input.all().map((i) => i.json.dedupe_key).filter(Boolean),
  },
}];

// Per config row: disabled -> skipped; no usable sink or no enabled
// source -> missing-data alert; otherwise 'configured'. Demo rows carry
// live:false; sheet rows default to live.
const on = (v) => String(v).toLowerCase() === 'yes';
const r = $json;
const live = r.live !== false;
const hasGmail = on(r.sink_gmail) && String(r.recipients_email || '').trim() !== '';
const hasSlack = on(r.sink_slack) && String(r.slack_channel || '').trim() !== '';
if (!on(r.enabled)) {
  return { json: { ...r, status: 'skipped', reason: 'enabled is not yes in the config tab', live } };
}
if (!hasGmail && !hasSlack) {
  return { json: { ...r, status: 'alerted', kind: 'missing-data', alert: `${r.client_id}: no usable sink — set sink_gmail + recipients_email or sink_slack + slack_channel in the config tab`, live } };
}
if (!on(r.src_meta_ads) && !on(r.src_google_ads) && !on(r.src_ga4)) {
  return { json: { ...r, status: 'alerted', kind: 'missing-data', alert: `${r.client_id}: no source enabled — set src_meta_ads, src_google_ads or src_ga4 to yes`, live } };
}
return { json: { ...r, status: 'configured', live } };

// One item per (client, enabled source) — the cell-level gate:
// a config flag flipped off simply never expands into a fetch. All-items
// mode because one client fans out to N source requests.
const on = (v) => String(v).toLowerCase() === 'yes';
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.status !== 'configured') { out.push({ json: r }); continue; }
  const sources = ['meta_ads', 'google_ads', 'ga4'].filter((s) => on(r['src_' + s]));
  for (const s of sources) {
    out.push({ json: {
      kind: 'source-request',
      client_id: r.client_id,
      client_name: r.client_name,
      source: s,
      report_date: $now.toISODate(),
      sinks: { gmail: on(r.sink_gmail), slack: on(r.sink_slack) },
      recipients_email: r.recipients_email || '',
      slack_channel: r.slack_channel || '',
      meta_ad_account_id: r.meta_ad_account_id || '',
      google_ads_customer_id: r.google_ads_customer_id || '',
      ga4_property_id: r.ga4_property_id || '',
      delivery_mode: String(r.delivery_mode || '').toLowerCase() === 'draft' ? 'draft' : 'send',
      brand_name: String(r.brand_name || '').trim(),
      brand_color: String(r.brand_color || '').trim(),
      brand_logo_url: String(r.brand_logo_url || '').trim(),
      alert_threshold_pct: (() => {
        const t = parseFloat(r.alert_threshold_pct);
        return Number.isFinite(t) ? t : null;
      })(),
      live: r.live === true,
      already_sent: String(r.already_sent || '').toLowerCase() === 'yes',
      sim_error_source: r.sim_error_source || '',
    } });
  }
}
return out;

// Meta insights rows (two 7-day buckets) -> adapter contract rows.
// All-items mode: one fetch response fans out to N metric rows. pairedItem
// recovers the matching request from the live? gate (fetch is 1:1).
const reqs = $('Meta Ads live?').all().map((i) => i.json);
const out = [];
for (const item of $input.all()) {
  const req = reqs[(item.pairedItem && item.pairedItem.item) || 0] || {};
  const rows = item.json.data || [];
  const cur = rows[rows.length - 1] || {};
  const prev = rows.length > 1 ? rows[rows.length - 2] : {};
  for (const metric of ['spend', 'impressions', 'clicks']) {
    out.push({ json: {
      kind: 'metric', client_id: req.client_id, client_name: req.client_name,
      source: 'meta_ads', report_date: req.report_date, metric,
      value: Number(cur[metric] || 0), prev_value: Number(prev[metric] || 0),
      sinks: req.sinks, recipients_email: req.recipients_email,
      slack_channel: req.slack_channel, live: true, already_sent: req.already_sent,
      delivery_mode: req.delivery_mode, brand_name: req.brand_name,
      brand_color: req.brand_color, brand_logo_url: req.brand_logo_url,
      alert_threshold_pct: req.alert_threshold_pct,
    } });
  }
}
return out;

