// Google Ads searchStream rows -> adapter contract rows (cost in dollars).
// All-items mode: one fetch response fans out to N metric rows. pairedItem
// recovers the matching request from the live? gate (fetch is 1:1).
const reqs = $('Google Ads live?').all().map((i) => i.json);
const out = [];
for (const item of $input.all()) {
  const req = reqs[(item.pairedItem && item.pairedItem.item) || 0] || {};
  const results = (item.json[0] && item.json[0].results) || item.json.results || [];
  const byWeek = {};
  for (const r of results) {
    const w = (r.segments && r.segments.week) || 'unknown';
    const m = r.metrics || {};
    byWeek[w] = byWeek[w] || { spend: 0, clicks: 0, conversions: 0 };
    byWeek[w].spend += Number(m.cost_micros || 0) / 1e6;
    byWeek[w].clicks += Number(m.clicks || 0);
    byWeek[w].conversions += Number(m.conversions || 0);
  }
  const weeks = Object.keys(byWeek).sort();
  const cur = byWeek[weeks[weeks.length - 1]] || {};
  const prev = byWeek[weeks[weeks.length - 2]] || {};
  for (const metric of ['spend', 'clicks', 'conversions']) {
    out.push({ json: {
      kind: 'metric', client_id: req.client_id, client_name: req.client_name,
      source: 'google_ads', report_date: req.report_date, metric,
      value: Math.round((cur[metric] || 0) * 100) / 100,
      prev_value: Math.round((prev[metric] || 0) * 100) / 100,
      sinks: req.sinks, recipients_email: req.recipients_email,
      slack_channel: req.slack_channel, live: true, already_sent: req.already_sent,
      delivery_mode: req.delivery_mode, brand_name: req.brand_name,
      brand_color: req.brand_color, brand_logo_url: req.brand_logo_url,
      alert_threshold_pct: req.alert_threshold_pct,
    } });
  }
}
return out;

