// GA4 runReport rows -> adapter contract rows (dateRange dimension picks
// the week bucket: 'date_range_0' = this week, 'date_range_1' = previous).
// All-items mode: one fetch response fans out to N metric rows. pairedItem
// recovers the matching request from the live? gate (fetch is 1:1).
const reqs = $('GA4 live?').all().map((i) => i.json);
const pairs = [['sessions', 0], ['conversions', 1]];
const out = [];
for (const item of $input.all()) {
  const req = reqs[(item.pairedItem && item.pairedItem.item) || 0] || {};
  const rows = item.json.rows || [];
  const sum = (bucket, idx) => rows
    .filter((r) => r.dimensionValues && r.dimensionValues[0].value === bucket)
    .reduce((acc, r) => acc + Number(r.metricValues[idx].value || 0), 0);
  for (const [metric, idx] of pairs) {
    out.push({ json: {
      kind: 'metric', client_id: req.client_id, client_name: req.client_name,
      source: 'ga4', report_date: req.report_date, metric,
      value: sum('date_range_0', idx), prev_value: sum('date_range_1', idx),
      sinks: req.sinks, recipients_email: req.recipients_email,
      slack_channel: req.slack_channel, live: true, already_sent: req.already_sent,
      delivery_mode: req.delivery_mode, brand_name: req.brand_name,
      brand_color: req.brand_color, brand_logo_url: req.brand_logo_url,
      alert_threshold_pct: req.alert_threshold_pct,
    } });
  }
}
return out;

// Demo adapter — emits the same contract rows the live 'ga4' adapter
// would, from the committed metrics fixture (injected at generation time).
// 'sim_error_source' on the config row fakes a source outage — the alert
// proves a failing source never blocks other clients. All-items mode:
