const METRICS = {
  "acme": [
    {
      "metric": "sessions",
      "value": 1240,
      "prev_value": 1100,
      "expected_delta_pct": 12.7
    },
    {
      "metric": "conversions",
      "value": 31,
      "prev_value": 30,
      "expected_delta_pct": 3.3
    }
  ],
  "boutique": [
    {
      "metric": "sessions",
      "value": 640,
      "prev_value": 640,
      "expected_delta_pct": 0.0
    }
  ],
  "coachlee": [
    {
      "metric": "sessions",
      "value": 95,
      "prev_value": 100,
      "expected_delta_pct": -5.0
    }
  ],
