    {
      "metric": "sessions",
      "value": 50,
      "prev_value": 40,
      "expected_delta_pct": 25.0
    }
  ]
};
const out = [];
for (const item of $input.all()) {
  const it = item.json;
  if (it.sim_error_source === 'ga4') {
    out.push({ json: {
      status: 'alerted', kind: 'failure',
      alert: `ga4 fetch failed for ${it.client_id} — simulated outage; other sources and clients are unaffected`,
      client_id: it.client_id, live: false,
    } });
    continue;
  }
  for (const m of (METRICS[it.client_id] || [])) {
    out.push({ json: {
      kind: 'metric', client_id: it.client_id, client_name: it.client_name,
      source: 'ga4', report_date: it.report_date, metric: m.metric,
      value: m.value, prev_value: m.prev_value,
      sinks: it.sinks, recipients_email: it.recipients_email,
      slack_channel: it.slack_channel, live: false, already_sent: it.already_sent,
      delivery_mode: it.delivery_mode, brand_name: it.brand_name,
      brand_color: it.brand_color, brand_logo_url: it.brand_logo_url,
      alert_threshold_pct: it.alert_threshold_pct,
    } });
  }
}
return out;

// EXTENSION DOCK — Source route's fallback output lands here. To add a
// source: add a Switch rule for its name, hang a fetch + normalize pair off
// the new output emitting the contract row
//   {kind:'metric', client_id, client_name, source, report_date, metric,
//    value, prev_value, sinks, recipients_email, slack_channel, live,
//    delivery_mode, brand_name, brand_color, brand_logo_url,
//    alert_threshold_pct}
// then wire it into Merge sources (raise its input count). The engine —
// deltas, grouping, prose, sinks, dedupe — needs no changes.
return $input.all().map((item) => ({
  json: {
    ...item.json,
    status: 'skipped',
    reason: `unhandled source '${item.json.source}' — dock a new adapter on this output`,
  },
}));

// Fetch-node error outputs land here (continueErrorOutput). One failing
// source becomes one failure alert — the other clients' items were
// never in this node's input, so they cannot be blocked.
const e = $json.error;
const msg = typeof e === 'string' ? e : ((e && e.message) || 'fetch failed');
return { json: {
  status: 'alerted', kind: 'failure',
  alert: `${$json.source || 'source'} fetch failed for ${$json.client_id || 'unknown'}: ${msg}`,
  client_id: $json.client_id || 'unknown', live: $json.live === true,
} };

// Deterministic math, never the AI's job: delta_pct = (value-prev)/prev.
// prev_value 0 -> delta null (not infinite); rendered 'n/a' downstream.
const it = $json;
if (it.kind !== 'metric') return { json: it };
const cur = Number(it.value) || 0;
const prev = Number(it.prev_value) || 0;
const delta = prev === 0 ? (cur === 0 ? 0 : null)
                         : Math.round(((cur - prev) / prev) * 1000) / 10;
return { json: { ...it, delta_pct: delta } };

// Metric rows -> one 'report-metrics' item per client. Alerts and skips
// pass straight through to the digest merge. Anomaly flags are computed
// here, deterministically: a metric is flagged when the row's
// alert_threshold_pct cell is a number and |delta_pct| >= threshold
// (delta null — prev week was zero — is never a flag). The AI only
// narrates the flags; it never decides them.
const out = [];
const byClient = {};
for (const item of $input.all()) {
  const j = item.json;
  if (j.kind !== 'metric') { out.push({ json: j }); continue; }
  const k = j.client_id;
  if (!byClient[k]) {
    byClient[k] = {
      status: 'report-metrics', client_id: j.client_id,
      client_name: j.client_name, report_date: j.report_date,
      metrics: [], sinks: j.sinks, recipients_email: j.recipients_email,
      slack_channel: j.slack_channel, live: j.live === true,
      already_sent: j.already_sent === true,
      delivery_mode: j.delivery_mode === 'draft' ? 'draft' : 'send',
      brand_name: j.brand_name || '', brand_color: j.brand_color || '',
      brand_logo_url: j.brand_logo_url || '',
      alert_threshold_pct: j.alert_threshold_pct,
      flags: [],
    };
  }
  const flagged = j.alert_threshold_pct != null && j.delta_pct != null
    && Math.abs(j.delta_pct) >= j.alert_threshold_pct;
  byClient[k].metrics.push({
    source: j.source, metric: j.metric, value: j.value,
    prev_value: j.prev_value, delta_pct: j.delta_pct, flagged,
  });
  if (flagged) {
    byClient[k].flags.push({
      source: j.source, metric: j.metric, delta_pct: j.delta_pct,
    });
  }
}
for (const k of Object.keys(byClient)) {
  byClient[k].flag_count = byClient[k].flags.length;
  out.push({ json: byClient[k] });
}
return out;

// Idempotency gate: dedupe_key = client_id + ISO week (kkkk-Wxx) — the
// report is a weekly artifact, so a re-run in the SAME week (not just the
// same day) is a duplicate. Live reads the 'reports' ledger collected at
// run start (lazy + guarded: an empty ledger is 'nothing sent', never a
// crash); demo rows carry 'already_sent' instead.
const it = $json;
const week = `${$now.weekYear}-W${String($now.weekNumber).padStart(2, '0')}`;
const key = `${it.client_id}__${week}`;
let dup = false;
if (it.live === true) {
  let sent = [];
  try { sent = $('Collect sent keys').first().json.sent_keys || []; }
  catch (e) { sent = []; }
  dup = sent.includes(key);
} else {
  dup = it.already_sent === true;
}
return { json: { ...it, dedupe_key: key, report_week: week, is_duplicate: dup } };

return { json: {
  status: 'alerted', kind: 'duplicate',
  alert: `${$json.client_id}: report ${$json.dedupe_key} already sent this week — skipped (idempotent re-run)`,
  client_id: $json.client_id, live: $json.live === true,
} };

// The AI only ever sees this precomputed table — it writes prose, never
// computes. System prompt forbids inventing numbers. Flagged anomalies are
// listed verbatim from the deterministic flags — the AI narrates them,
// it never decides them.
const it = $json;
const rows = it.metrics.map((m) =>
  `| ${m.source} | ${m.metric} | ${m.value} | ${m.prev_value} | ${m.delta_pct === null ? 'n/a' : m.delta_pct + '%'}${m.flagged ? ' FLAGGED' : ''} |`);
const table = [
  '| source | metric | this week | last week | WoW |',
  '| --- | --- | --- | --- | --- |',
  ...rows,
].join('\n');
const flagLines = (it.flags || []).map((f) =>
  `- ${f.source} ${f.metric}: ${f.delta_pct}% WoW (threshold ${it.alert_threshold_pct}%)`);
const flagBlock = flagLines.length
  ? `\n\nFlagged anomalies (|WoW| >= ${it.alert_threshold_pct}%):\n${flagLines.join('\n')}`
  : '';
return { json: {
  ...it,
  metric_table: table,
  messages: [
    { role: 'system', content: 'You write short client-facing weekly marketing report summaries. Every number is already computed in the table below — quote it, never recalculate or invent figures. Metrics marked FLAGGED crossed the client alert threshold — narrate them as anomalies calling for attention, using the listed numbers only. Note the strongest win, the biggest risk, and one recommended next step. 3-5 sentences, plain language.' },
    { role: 'user', content: `Client: ${it.client_name}\nWeek ending: ${it.report_date}\n\n${table}${flagBlock}` },
  ],
} };

// The OpenAI node replaces the item with its response — restore the
// report fields from the prompt node (paired item) and keep the prose.
const src = $('Build report prompt').item.json;
const msg = $json.message;
const narrative = (msg && msg.content) || '';
return { json: { ...src, narrative } };

// Deterministic stand-in for the AI node — same {narrative} contract,
// zero credentials, and it only quotes the precomputed deltas.
const it = $json;
const up = it.metrics.filter((m) => (m.delta_pct || 0) > 0).map((m) => `${m.metric} up ${m.delta_pct}%`);
const down = it.metrics.filter((m) => (m.delta_pct || 0) < 0).map((m) => `${m.metric} down ${Math.abs(m.delta_pct)}%`);
const flagText = (it.flags || []).length
  ? ` Flagged anomalies: ${it.flags.map((f) => `${f.source}/${f.metric} ${f.delta_pct}%`).join('; ')}.`
  : '';
const narrative = `${it.client_name}: this week ${up.join('; ') || 'metrics held flat'}${down.length ? '; watch ' + down.join('; ') : ''}.${flagText} (demo prose — no AI call)`;
return { json: { ...it, narrative } };

// {subject, body_markdown, body_html, recipients} — the sink contract
// every delivery adapter consumes. body_html renders the per-client brand
// cells (brand_name / brand_color / brand_logo_url) into an email-safe
// header: inline styles only, and an absent logo simply renders no <img> —
// the layout never depends on it.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const it = $json;
const brand = it.brand_name || it.client_name;
const color = /^#[0-9a-fA-F]{3,8}$/.test(it.brand_color || '') ? it.brand_color : '#33475b';
const logo = (it.brand_logo_url || '').trim();
const subject = `${brand} — weekly report (${it.report_date})`;
const flagNote = (m) => m.flagged ? ' <strong style="color:#b91c1c;">FLAGGED</strong>' : '';
const metricRows = it.metrics.map((m) =>
  `<tr${m.flagged ? ' style="background:#fff4e5;"' : ''}><td style="padding:6px 10px;border:1px solid #e3e3e3;">${esc(m.source)}</td><td style="padding:6px 10px;border:1px solid #e3e3e3;">${esc(m.metric)}</td><td style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">${m.value}</td><td style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">${m.prev_value}</td><td style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">${m.delta_pct === null ? 'n/a' : m.delta_pct + '%'}${flagNote(m)}</td></tr>`);
const flagItems = (it.flags || []).map((f) =>
  `<li>${esc(f.source)} ${esc(f.metric)}: ${f.delta_pct}% WoW</li>`).join('');
const flagSection = flagItems
  ? `<div style="margin:14px 0;padding:10px 14px;background:#fff4e5;border-left:4px solid #d97706;"><strong>Flagged anomalies</strong> (|WoW| &ge; ${it.alert_threshold_pct}%)<ul style="margin:6px 0 0 18px;padding:0;">${flagItems}</ul></div>`
  : '';
const logoBlock = logo
  ? `<img src="${esc(logo)}" alt="${esc(brand)}" style="max-height:40px;display:block;margin-bottom:10px;">`
  : '';
const bodyHtml = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#222;">
  <div style="background:${color};padding:18px 24px;border-radius:8px 8px 0 0;">
    ${logoBlock}<div style="color:#ffffff;font-size:20px;font-weight:bold;">${esc(brand)}</div>
    <div style="color:rgba(255,255,255,0.85);font-size:12px;">Weekly report — week ending ${esc(it.report_date)}</div>
  </div>
  <div style="border:1px solid #e3e3e3;border-top:none;padding:20px 24px;border-radius:0 0 8px 8px;">
    <table style="border-collapse:collapse;width:100%;font-size:13px;">
      <tr><th style="padding:6px 10px;border:1px solid #e3e3e3;text-align:left;">source</th><th style="padding:6px 10px;border:1px solid #e3e3e3;text-align:left;">metric</th><th style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">this week</th><th style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">last week</th><th style="padding:6px 10px;border:1px solid #e3e3e3;text-align:right;">WoW</th></tr>
      ${metricRows.join('')}
    </table>
    ${flagSection}
    <p style="font-size:14px;line-height:1.5;">${esc(it.narrative)}</p>
    <p style="font-size:11px;color:#888;">— weekly client report</p>
  </div>
</div>`;
const flagMd = flagItems ? `\n\nFlagged anomalies (|WoW| >= ${it.alert_threshold_pct}%):\n` + (it.flags || []).map((f) => `- ${f.source} ${f.metric}: ${f.delta_pct}% WoW`).join('\n') : '';
const body = `# ${it.client_name} — week ending ${it.report_date}\n\n${it.metric_table}${flagMd}\n\n${it.narrative}\n\n— weekly client report`;
return { json: { ...it, status: 'report-built', subject, body_markdown: body, body_html: bodyHtml } };

// One item per enabled sink — sink flags are cells, so delivery channels
// toggle without touching the workflow. All-items mode: one report fans
// out to N sink sends.
const out = [];
for (const item of $input.all()) {
  const it = item.json;
  const before = out.length;
  if (it.sinks && it.sinks.gmail) out.push({ json: { ...it, sink: 'gmail', to: it.recipients_email } });
  if (it.sinks && it.sinks.slack) out.push({ json: { ...it, sink: 'slack', to: it.slack_channel } });
  if (out.length === before) out.push({ json: { ...it, status: 'alerted', kind: 'missing-data', alert: `${it.client_id}: report built but no sink enabled` } });
}
return out;

// Gmail send replaces the item with its response — recover the report
// fields from the paired 'Fan out sinks' item.
const req = $('Fan out sinks').item.json;
return { json: { status: 'sink-ok', sink: 'gmail', delivery_mode: 'send', dedupe_key: req.dedupe_key, client_id: req.client_id, to: req.to, flag_count: req.flag_count || 0, flags: req.flags || [], live: true } };

// Same recovery as 'Mark email sent' — a created draft still counts as
// delivered for the ledger (re-runs must not re-draft), the sink-ok item
// just records delivery_mode='draft'.
const req = $('Fan out sinks').item.json;
return { json: { status: 'sink-ok', sink: 'gmail', delivery_mode: 'draft', dedupe_key: req.dedupe_key, client_id: req.client_id, to: req.to, flag_count: req.flag_count || 0, flags: req.flags || [], live: true } };

return $input.all().map((item) => ({ json: {
  status: 'sink-ok', sink: 'gmail', delivery_mode: 'send',
  dedupe_key: item.json.dedupe_key, client_id: item.json.client_id,
  to: item.json.to, flag_count: item.json.flag_count || 0,
  flags: item.json.flags || [],
  note: 'demo — email not sent', live: false,
} }));

return $input.all().map((item) => ({ json: {
  status: 'sink-ok', sink: 'gmail', delivery_mode: 'draft',
  dedupe_key: item.json.dedupe_key, client_id: item.json.client_id,
  to: item.json.to, flag_count: item.json.flag_count || 0,
  flags: item.json.flags || [],
  note: 'demo — draft created, not sent', live: false,
} }));

return $input.all().map((item) => ({ json: {
  status: 'sink-ok', sink: 'slack', dedupe_key: item.json.dedupe_key,
  client_id: item.json.client_id, to: item.json.to,
  flag_count: item.json.flag_count || 0, flags: item.json.flags || [],
  note: 'demo — slack post not sent', live: false,
} }));

// Sink-side attach point — add a Switch rule for the new sink's name and
// a live/demo pair that consumes {subject, body_markdown, body_html, to}
// and emits {status:'sink-ok', sink, dedupe_key, client_id, delivery_mode,
// flag_count, flags} into Merge sends.
return $input.all().map((item) => ({
  json: { ...item.json, status: 'skipped', reason: `unhandled sink '${item.json.sink}' — dock a new sink adapter on this output` },
}));

// Delivery/record failures land here from the error outputs — one failed
// sink alerts while the rest of the report (and other clients) finish.
const e = $json.error;
const msg = typeof e === 'string' ? e : ((e && e.message) || 'delivery failed');
let req = {};
try { req = $('Fan out sinks').item.json; } catch (err) { req = {}; }
return { json: {
  status: 'alerted', kind: 'failure',
  alert: `report delivery failed for ${req.client_id || $json.client_id || 'unknown'} via ${req.sink || 'sink'}: ${msg}`,
  client_id: req.client_id || $json.client_id || 'unknown',
  live: req.live === true || $json.live === true,
} };

// Sink results -> one 'reported' item per dedupe_key. Anything that is
// not a send result (dock skips) passes through.
const byReport = {};
const passthrough = [];
for (const i of $input.all()) {
  const j = i.json;
  if (j.status !== 'sink-ok') { passthrough.push({ json: j }); continue; }
  if (!byReport[j.dedupe_key]) {
    byReport[j.dedupe_key] = {
      status: 'reported', dedupe_key: j.dedupe_key, client_id: j.client_id,
      sinks_sent: [], live: j.live === true,
      flag_count: j.flag_count || 0, flags: j.flags || [],
      delivery_mode: j.delivery_mode || 'send',
    };
  }
  const sinkLabel = j.delivery_mode === 'draft' && j.sink === 'gmail' ? 'gmail(draft)' : j.sink;
  byReport[j.dedupe_key].sinks_sent.push(sinkLabel);
}
return [...Object.values(byReport).map((r) => ({ json: r })), ...passthrough];

// Demo ledger write mirror — reports get a demo 'reported' marker,
// non-report items pass through untouched.
return $input.all().map((item) => ({
  json: item.json.status === 'reported'
    ? { ...item.json, demo_note: `would upsert reports row ${item.json.dedupe_key}` }
    : item.json,
}));

// Exactly one item per run — runOnceForAllItems over the merged wave.
// anomaly_flags counts the deterministic per-metric flags carried on each
// reported item (|delta_pct| >= the client's alert_threshold_pct cell).
const items = $input.all();
const alerts = items.filter((i) => i.json.status === 'alerted').map((i) => i.json.alert);
const reportedItems = items.filter((i) => i.json.status === 'reported');
const reported = reportedItems.length;
const skipped = items.filter((i) => i.json.status === 'skipped').length;
const flaggedMetrics = reportedItems.flatMap((i) =>
  (i.json.flags || []).map((f) => `${i.json.client_id}: ${f.source}/${f.metric} ${f.delta_pct}%`));
return [{ json: {
  status: 'digest',
  summary: `Run complete: ${reported} report(s) delivered, ${skipped} skipped, ${alerts.length} alert(s), ${flaggedMetrics.length} anomaly flag(s)`,
  reports_delivered: reported,
  skipped,
  anomaly_flags: flaggedMetrics.length,
  flagged_metrics: flaggedMetrics,
  needs_attention: alerts,
  live: items.some((i) => i.json.live === true),
} }];

// {to} in from 'Operator email', digest fields out to the Gmail node.
// The lane guard: 'Operator email' also fires inside error-triggered
// executions (its other input), where 'Run digest' has no data — the
// lookup then throws and this returns zero items, so the digest email
// never fires on a failure alert.
let d;
try { d = $('Run digest').first().json; } catch (e) { return []; }
const to = $input.first().json.to || 'owner@example.com';
const alerts = (d.needs_attention || []).map((a) => `- ${a}`).join('\n');
const flags = (d.flagged_metrics || []).map((f) => `- ${f}`).join('\n');
return [{ json: {
  to,
  subject: `Weekly client reports: ${d.reports_delivered} delivered, ${d.skipped} skipped, ${(d.needs_attention || []).length} alert(s)`,
  body: `${d.summary}${alerts ? `\n\nNeeds attention:\n${alerts}` : ''}${flags ? `\n\nAnomaly flags:\n${flags}` : ''}`,
} }];

// One seed item per tab — 'tab' routes through the Switch and is stripped
// before the append (an empty sheet autoMaps headers from item keys, so a
// stray 'tab' key would become a real column). The reports seed must carry
// dedupe_key — it is the appendOrUpdate matching column downstream.
return [
  { json: { tab: 'config', client_id: 'acme', client_name: 'Acme Retail (example)', enabled: 'yes', src_meta_ads: 'yes', src_google_ads: 'yes', src_ga4: 'yes', sink_gmail: 'yes', sink_slack: 'no', recipients_email: 'client@example.com', slack_channel: '', meta_ad_account_id: '', google_ads_customer_id: '', ga4_property_id: '', delivery_mode: 'send', brand_name: '', brand_color: '', brand_logo_url: '', alert_threshold_pct: '' } },
  { json: { tab: 'reports', dedupe_key: 'acme__2026-W41', client_id: 'acme', report_week: '2026-W41', sinks_sent: 'gmail', sent_at: '2026-10-06T09:00:00.000Z' } },
];

// Strip the 'tab' routing key — only real columns survive, so the
// empty-sheet autoMap writes a clean header row.
return $input.all().map((item) => {
  const { tab, ...cols } = item.json;
  return { json: cols };
});

// Strip the 'tab' routing key — only real columns survive, so the
// empty-sheet autoMap writes a clean header row.
return $input.all().map((item) => {
  const { tab, ...cols } = item.json;
  return { json: cols };
});

const created = $('Create report workbook').first().json;
const id = created.spreadsheetId || created.id || '';
return [{ json: {
  spreadsheet_id: id,
  next_step: 'Paste spreadsheet_id into the Workflow Config node, set your email in the Operator email node, fill the config tab with your clients, then delete this setup lane.',
} }];
